def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    counts={}
    for r in range(h):
        for c in range(w):
            counts[grid[r][c]]=counts.get(grid[r][c],0)+1
    bg=max(counts,key=counts.get)
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or counts[color]<2: continue
            for dr,dc in [(-1,-1),(-1,1),(1,-1),(1,1)]:
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and grid[nr][nc]==color:
                    rr,cc=r-dr,c-dc
                    while 0<=rr<h and 0<=cc<w:
                        out[rr][cc]=color; rr-=dr; cc-=dc
                    break
    return out
